ALTER TABLE public.weighbridge_transactions ADD COLUMN disposer_signature text, ADD COLUMN disposer_name text, ADD COLUMN disposer_signoff_at timestamptz;
ALTER TABLE public.route_one_jobs ADD COLUMN disposer_signature text, ADD COLUMN disposer_name text, ADD COLUMN disposer_signoff_at timestamptz;
CREATE OR REPLACE FUNCTION public.sync_waste_out_producer_signature() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ BEGIN IF NEW.job_type = 'waste_out' THEN UPDATE public.route_one_jobs SET customer_signature = NEW.operator_signature, customer_signoff_name = NEW.operator_name, customer_signoff_at = CASE WHEN NEW.operator_signature IS NOT NULL THEN NEW.first_weigh_at ELSE NULL END WHERE weighbridge_transaction_id = NEW.id AND job_type = 'waste_out_skip'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER sync_waste_out_producer_signature AFTER UPDATE OF operator_signature, operator_name ON public.weighbridge_transactions FOR EACH ROW EXECUTE FUNCTION public.sync_waste_out_producer_signature();